// Fires when any workflow that names this one in settings.errorWorkflow fails.
// The point is that you find out from this node, not from a customer.
//
// Payload shape verified against v2.48.6
// (packages/nodes-base/nodes/ErrorTrigger/ErrorTrigger.node.ts):
//   { execution: { id, url, error, lastNodeExecuted, mode },
//     workflow:  { id, name } }
// The workflow name is NOT inside `execution` - reading it there yields
// undefined, which is how an alert ends up saying workflow "unknown".
const exec = $json.execution || {};
const wf = $json.workflow || {};
const err = exec.error || {};

const code = Number(err.httpCode || err.statusCode || err.status || 0);
const kelas = (code === 429 || code === 408 || code >= 500) ? 'TEMPORARY' : 'PERMANENT';

// `lastNodeExecuted` is the reliable one; error.node only exists for node-level
// errors, not for expression or workflow-level failures.
const failedNode = exec.lastNodeExecuted || (err.node ? err.node.name : null);

return [{
  json: {
    workflow: wf.name || wf.id || 'unknown',
    workflow_id: wf.id || null,
    failed_node: failedNode,
    class: kelas,
    http_code: code || null,
    message: String(err.message || '').slice(0, 300),
    execution_id: exec.id || null,
    mode: exec.mode || null,
    // Enough to decide: page someone now, or read it in the morning.
    alert_level: kelas === 'TEMPORARY' ? 'digest' : 'immediate',
  },
}];

// Placeholder for the transport you actually use (Telegram, Slack, email).
// Left as a Code node so this workflow imports and runs with no
// credentials - swap it for your channel node before going live.
return [{ json: { sent: true, channel: 'unconfigured',
  would_send: $json } }];
